package ch.ubique.libs.kmpanion.compose.image

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.foundation.border
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.size
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.platform.LocalInspectionMode
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * Decode an image from the Base64 [encodedImage], displaying the [placeholder] composable while it is being decoded
 *
 * @param encodedImage The Base64 encoded image string
 * @param modifier The modifier applied to the [Image] composable
 * @param contentScale The image scale to be used, defaults to [ContentScale.Fit]
 * @param contentDescription The image content description
 * @param placeholder A composable that is being shown while the image is being decoded
 *
 * @throws IllegalArgumentException If the Base64 string cannot be decoded
 */
@Composable
fun Base64Image(
	encodedImage: String,
	modifier: Modifier = Modifier,
	contentScale: ContentScale = ContentScale.Fit,
	contentDescription: String? = null,
	placeholder: @Composable () -> Unit = {},
	error: @Composable () -> Unit = {},
) {
	val imageBitmap = rememberBase64Drawable(encodedImage)
	imageBitmap.value?.let { result ->
		if (result.isSuccess) {
			Image(result.getOrThrow(), contentDescription = contentDescription, contentScale = contentScale, modifier = modifier)
		} else {
			error()
		}
	} ?: placeholder()

}

@Composable
private fun rememberBase64Drawable(encodedImage: String): State<Result<ImageBitmap>?> {
	return if (LocalInspectionMode.current) {
		// Decode synchronously for the inspection preview
		remember {
			val result = try {
				Result.success(decodeBase64Bitmap(encodedImage))
			} catch (e: Exception) {
				Result.failure(e)
			}
			mutableStateOf(result)
		}
	} else {
		// Produce the bitmap drawable state on the IO dispatcher because decoding can take quite a few milliseconds
		val initial: Result<ImageBitmap>? = null
		produceState(initialValue = initial, key1 = encodedImage) {
			withContext(Dispatchers.IO) {
				value = try {
					Result.success(decodeBase64Bitmap(encodedImage))
				} catch (e: Exception) {
					Result.failure(e)
				}
			}
		}
	}
}

private fun decodeBase64Bitmap(encodedImage: String): ImageBitmap {
	val rawImage = Base64.decode(encodedImage, Base64.DEFAULT)
	val bitmap = BitmapFactory.decodeByteArray(rawImage, 0, rawImage.size)
	return bitmap.asImageBitmap()
}

@Preview(showBackground = true)
@Composable
private fun Base64ImagePreview() {
	Column(Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
		Base64Image(
			encodedImage = "",
			placeholder = { CircularProgressIndicator() },
			modifier = Modifier
				.size(80.dp)
				.border(1.dp, Color.LightGray),
		)

		Base64Image(
			encodedImage = "asdf",
			placeholder = { CircularProgressIndicator() },
			error = { Text("Decoding failed") },
			modifier = Modifier
				.size(80.dp)
				.border(1.dp, Color.LightGray)
		)
	}
}